'use strict';
// Single-file engineering comparisons: both phases always execute, tabs only browse.
const egBase={workbench,configPanel,handleAction,modalContent,closeModal,validate,configurationFragment,resultContent,exportRows,doExport,twMountPreview,tcOutput};
const EG_STAGES=[['duplicate','重复项目'],['parent','主子项目']];
const egView={stage:'duplicate',panel:'materials',query:'',page:1,size:20,task:null,resultKind:'duplicate',resultQuery:'',resultDoc:'all',resultMethod:'all',resultPage:1,resultSize:20};
let egSourceReturn=null;
function egActive(){return state.view==='tool'&&state.toolId==='engineering';}
function egPreparing(){return egActive()&&!currentTask();}
function egConfig(){return currentTask()?.config||ws().config;}
function egGroup(key=egView.stage){return egConfig().engineering[key];}
function egText(value){return value===null||value===undefined?'未提供':typeof value==='object'?JSON.stringify(value,null,2):String(value);}
function egFileIssue(d,c=egConfig()){
 if(!d||d.deleted)return '文件已移除';if(!d.rows||!Array.isArray(d.columns))return '需要台账表格';
 const required=[...new Set(EG_STAGES.flatMap(([k])=>(c.engineering[k]?.rows||[]).map(r=>r.a)).filter(Boolean))],missing=required.filter(col=>!d.columns.includes(col));
 return missing.length?'缺少列：'+missing.join('、'):'';
}
function egMaterials(){const root=document.createElement('div');root.innerHTML=twMaterials();const heading=root.querySelector('.tw-panel-head');heading.innerHTML='<h2><span class="tw-step">Step 1</span> 项目台账</h2>'+B('添加台账','add-tool-materials','soft sm');const intro=root.querySelector('.tw-intro');if(intro)intro.textContent='添加项目台账，分别查找每张表内的重复项目和主子项目。';root.querySelectorAll('.tw-tree-row').forEach(row=>{const id=row.querySelector('[data-action="tw-preview"]')?.dataset.id,issue=egFileIssue(file(id));row.insertAdjacentHTML('beforeend','<small class="eg-file-status '+(issue?'eg-warning':'')+'" title="'+E(issue||'本次比较字段在此表中均可找到')+'">'+E(issue||'比较列已对应')+'</small>');});root.querySelector('aside')?.classList.add('eg-materials');return root.innerHTML;}
function egFields(){const g=egGroup(),q=egView.query.trim().toLowerCase();return g.rows.map((r,index)=>({r,index})).filter(({r})=>[r.name,r.a,r.rule].join(' ').toLowerCase().includes(q));}
function egFieldTable(){const g=egGroup(),locked=!!currentTask(),rows=egFields(),pages=Math.max(1,Math.ceil(rows.length/egView.size));egView.page=Math.max(1,Math.min(egView.page,pages));return '<div class="eg-table-scroll"><table class="eg-table"><thead><tr><th>比较内容</th><th>台账列</th><th>比较方式</th><th>权重</th><th>操作</th></tr></thead><tbody>'+rows.slice((egView.page-1)*egView.size,egView.page*egView.size).map(({r,index})=>'<tr><td>'+E(r.name)+'</td><td>'+E(r.a)+'</td><td>'+E(COMPARE_TYPES.find(x=>x[0]===r.type)?.[1]||r.type)+'</td><td>'+Number((+r.weight*100).toFixed(2))+'%</td><td>'+A(locked?'查看':'编辑','eg-field','data-index="'+index+'"')+'</td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="eg-empty">'+(egView.query?'没有匹配的比较字段。':'请添加比较字段，或从提示词库载入配套字段。')+'</div>':'')+'</div><div class="eg-pager"><span>共 <strong>'+rows.length+'</strong> 个字段</span><label>每页 <select data-eg-change="field-size" aria-label="每页比较字段数">'+[20,50,100].map(n=>'<option value="'+n+'" '+(n===egView.size?'selected':'')+'>'+n+'</option>').join('')+'</select> 个</label><div>'+B('上一页','eg-field-page','sm','data-step="-1" '+(egView.page===1?'disabled':''))+'<span>第 '+egView.page+' / '+pages+' 页</span>'+B('下一页','eg-field-page','sm','data-step="1" '+(egView.page===pages?'disabled':''))+'</div></div>';}
function egPaintFields(){const box=$('#eg-field-list');if(box)box.innerHTML=egFieldTable();}
function egPanel(){const c=egConfig(),g=egGroup(),locked=!!currentTask(),s=c.stages[egView.stage];return '<aside class="config ew-config tw-config pg-config eg-config"><div class="eg-panel-head"><h2><span class="tw-step">'+(locked?'执行配置':'Step 2')+'</span> 设置项目比较</h2>'+'</div><p class="eg-intro">两类分析同时执行；下方分别设置各自的比较字段与规则。</p><nav class="eg-stage-tabs" aria-label="查看不同项目关系的设置">'+EG_STAGES.map(([key,n])=>'<button data-action="eg-stage" data-stage="'+key+'" aria-pressed="'+(egView.stage===key)+'" class="'+(egView.stage===key?'active':'')+'">'+n+'</button>').join('')+'</nav><section class="pg-stage-card eg-prompt" data-pg-stage-card="'+egView.stage+'"><label class="pg-select-label"><span>分析提示词</span>'+pgSelect('engineering',egView.stage,s,'data-pg-prompt="'+egView.stage+'" '+(locked?'disabled':''))+'</label>'+B(locked?'查看提示词':'编辑提示词','aw-prompt','sm','data-stage="'+egView.stage+'"')+'</section><div class="eg-criteria"><label>候选判定分数<input type="number" min="0" max="5" step=".05" data-eg-config="threshold" aria-label="'+(egView.stage==='parent'?'主子项目':'重复项目')+'候选判定分数" value="'+g.threshold+'" '+(locked?'readonly':'')+'><span>/ 5 分及以上</span></label><span>字段权重合计 <strong>'+Number(g.rows.reduce((n,r)=>n+(+r.weight||0),0)*100).toFixed(1).replace(/\.0$/,'')+'%</strong></span>'+B(locked?'查看比较设置':'更多比较设置','eg-options','sm')+'</div><div class="eg-field-toolbar"><div><h3>比较字段 <strong>'+g.rows.length+'</strong></h3><small>每份台账使用以下列名，执行前逐份校验。</small></div><div class="search">'+I('search','icon-sm')+'<input data-eg-input="fields" aria-label="查找比较字段" placeholder="查找字段或评分规则" value="'+E(egView.query)+'"></div>'+(!locked?B('添加字段','eg-field-new','soft sm'):'')+'</div><div class="eg-field-list" id="eg-field-list">'+egFieldTable()+'</div></aside>';}
configPanel=function(){return egActive()?egPanel():egBase.configPanel();};
workbench=function(){if(!egPreparing())return egBase.workbench();const w=ws();if(!w.ids.includes(w.preview))w.preview=w.ids[0]||null;return '<div class="ew-workspace tw-workspace eg-workspace">'+twHeader()+'<nav class="eg-mobile-tabs" aria-label="工程分析工作区">'+B('项目台账','eg-panel',egView.panel==='materials'?'active':'','data-panel="materials"')+B('比较设置','eg-panel',egView.panel==='config'?'active':'','data-panel="config"')+'</nav><div class="eg-layout" data-eg-panel="'+egView.panel+'">'+egMaterials()+egPanel()+'</div></div>';};
twMountPreview=function(){if(egPreparing())return;return egBase.twMountPreview();};
function egFieldDraft(index=-1){return{stage:egView.stage,index,draft:index>=0?structuredClone(egGroup().rows[index]):{key:'F'+(Math.max(0,...egGroup().rows.map(r=>Number(r.key.slice(1))||0))+1),name:'',a:'',type:'similarity',threshold:.8,weight:0,rule:''}};}
function egFieldModal(){const p=modalData,r=p.draft,locked=!!currentTask(),cols=[...new Set([r.a,...selectedDocs(currentTask()?.ids||ws().ids).flatMap(d=>d.columns||[])].filter(Boolean))];return modalFrame(locked?'查看比较字段':p.index<0?'添加比较字段':'编辑比较字段','说明比较哪一列，以及如何计分。','<div class="eg-form-grid"><label class="field"><span>比较内容</span><input data-eg-edit="name" aria-label="比较内容" value="'+E(r.name)+'" '+(locked?'readonly':'')+'></label><label class="field"><span>台账列名</span><input list="eg-source-columns" data-eg-edit="a" aria-label="台账列名" value="'+E(r.a)+'" '+(locked?'readonly':'')+'><datalist id="eg-source-columns">'+cols.map(v=>'<option value="'+E(v)+'"></option>').join('')+'</datalist></label><label class="field"><span>比较方式</span><select data-eg-edit="type" '+(locked?'disabled':'')+'>'+COMPARE_TYPES.filter(([k])=>k!=='investment_gt'||p.stage==='parent').map(([v,n])=>'<option value="'+v+'" '+(r.type===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label class="field"><span>预筛阈值（0–1）</span><input type="number" min="0" max="1" step=".01" data-eg-edit="threshold" value="'+r.threshold+'" '+(locked?'readonly':'')+'></label><label class="field"><span>评分权重（%）</span><input type="number" min="0" max="100" step="1" data-eg-edit="weight" value="'+(+r.weight*100)+'" '+(locked?'readonly':'')+'></label></div><p class="eg-form-note">预筛先缩小比较范围；最终候选按加权总分判断。金额差异按比例填写，例如0.04表示4%。</p><label class="field"><span>评分规则</span><textarea rows="5" data-eg-edit="rule" '+(locked?'readonly':'')+'>'+E(r.rule)+'</textarea></label><p id="eg-field-error" class="error" role="alert"></p>',B(locked?'关闭':'取消','close-modal')+(locked?'':(p.index>=0?B('删除字段','eg-field-delete','danger ghost'):'')+B('保存字段','eg-field-save','primary')),'eg-field-dialog');}
function egOptionsModal(){const g=modalData.draft,locked=!!currentTask(),single=g.singleTable||{},llm=single.llm_config||{};return modalFrame(locked?'查看比较设置':'更多比较设置','设置预筛范围和补充检查要求。','<label class="field"><span>至少匹配的字段数</span><input type="number" min="1" max="'+g.rows.length+'" data-eg-option="minFields" value="'+g.minFields+'" '+(locked?'readonly':'')+'></label><p class="eg-form-note">预筛时至少有这些字段达到各自的比较阈值，才进入后续比较。</p><label class="field"><span>补充检查要求</span><textarea rows="5" data-eg-option="additional" '+(locked?'readonly':'')+'>'+E(g.additional||'')+'</textarea></label>'+(modalData.stage==='duplicate'?'<label class="eg-check"><input type="checkbox" data-eg-option="phase" '+(llm.phase_check_enabled!==false?'checked':'')+' '+(locked?'disabled':'')+'>区分一期、二期等分期项目</label><label class="field"><span>用于识别分期的列</span><select data-eg-option="phaseField" '+(locked?'disabled':'')+'>'+g.rows.map(r=>'<option value="'+E(r.key)+'" '+((llm.phase_check_field||g.rows[0]?.key)===r.key?'selected':'')+'>'+E(r.a||r.name)+'</option>').join('')+'</select></label>':'')+'<p id="eg-options-error" class="error" role="alert"></p>',B(locked?'关闭':'取消','close-modal')+(locked?'':B('保存设置','eg-options-save','primary')),'medium');}
function egSingle(g,key){const src=structuredClone(g.singleTable||{}),llm=src.llm_config||{},rows=g.rows,aux=src.auxiliary_columns||['文件名称','source_file'];const fields=Object.fromEntries(rows.map(r=>[r.key,{...(src.field_mapping?.[r.key]||{}),excel_column:r.a,compare_type:r.type,threshold:+r.threshold,skip_if_both_empty:r.skipIfBothEmpty??src.field_mapping?.[r.key]?.skip_if_both_empty??false,count_toward_min_match:r.countTowardMinMatch??src.field_mapping?.[r.key]?.count_toward_min_match??true,value_normalizer:r.valueNormalizer??src.field_mapping?.[r.key]?.value_normalizer??(r.type.startsWith('investment')?'float':'none')} ]));return{...src,threshold:+g.threshold,field_mapping:fields,logical_field_mapping:Object.fromEntries(rows.map(r=>[r.key,r.a])),columns_to_read:[...new Set([...rows.map(r=>r.a),...aux].filter(Boolean))],auxiliary_columns:aux,column_aliases:src.column_aliases||{},prescreen_config:{investment_gt_direction:key==='parent'?'current_gt_other':'bidirectional',investment_fallback_pairs:false,...src.prescreen_config,min_match_fields:+g.minFields},llm_config:{hard_rules:[],veto_rules:[],phase_check_field:rows[0]?.key||'',phase_check_enabled:key==='duplicate',strict_negative_prompt:'',output_schema:key==='parent'?'parent_child_v1':'duplicate_v1',arbitration:{enabled:false,lower_delta:.25,upper_delta:.2,prefer:'system'},system_rules:{},...llm,threshold:+g.threshold,threshold_comparison:'gte',field_weights:Object.fromEntries(rows.map(r=>[r.key,+r.weight])),field_prompt_rules:Object.fromEntries(rows.map(r=>[r.key,r.rule])),additional_prompt:g.additional||''}};}
configurationFragment=function(id,c){if(id!=='engineering')return egBase.configurationFragment(id,c);const dd=egSingle(c.engineering.duplicate,'duplicate'),pc=egSingle(c.engineering.parent,'parent'),stage=(key,block)=>{const s=c.stages[key],prompt=block.llm_config.additional_prompt||s.content||'';block.prompt=prompt;block.llm_config.additional_prompt=prompt;return{key:s.backendId??s.template,prompt};};return{exec_mode:'custom',custom_config:{mode:'engineering_project',engineering_repeat_project:stage('duplicate',dd),engineering_sub_project:stage('parent',pc),threshold:dd.threshold,duplicate_threshold:dd.threshold,parent_child_threshold:pc.threshold,duplicate_detection:dd,parent_child_analysis:pc}};};
validate=function(show=true){if(!egPreparing())return egBase.validate(show);const c=egConfig(),errors=egBase.validate(false).filter(e=>!EG_STAGES.some(([,label])=>e.startsWith(label))&&!e.endsWith('的字段对应不完整'));for(const [key,label] of EG_STAGES){const g=c.engineering[key],sum=g.rows.reduce((n,r)=>n+(+r.weight>0?+r.weight:0),0);if(!g.rows.length)errors.push(label+'至少添加一个比较字段。');if(Math.abs(sum-1)>.02||sum<=0)errors.push(label+'的字段权重合计应为100%。');if(new Set(g.rows.map(r=>r.key)).size!==g.rows.length)errors.push(label+'字段标识重复，请检查字段配置。');for(const r of g.rows){if(!r.name?.trim()||!r.a?.trim()||r.a==='请选择')errors.push(label+'请填写比较内容和台账列名。');if(!Number.isFinite(+r.weight)||+r.weight<0||+r.weight>1||!Number.isFinite(+r.threshold)||+r.threshold<0||+r.threshold>1)errors.push(label+'的权重或预筛阈值超出范围。');if(+r.weight>0&&!r.rule?.trim())errors.push(label+'参与评分的字段需要填写评分规则。');if(key==='duplicate'&&r.type==='investment_gt')errors.push('重复项目不能使用“金额大于”比较。');}if(!Number.isFinite(+g.threshold)||+g.threshold<0||+g.threshold>5)errors.push(label+'候选判定分数应为0–5分。');if(!Number.isInteger(+g.minFields)||+g.minFields<1||+g.minFields>g.rows.length)errors.push(label+'至少匹配的字段数应在当前字段数范围内。');}for(const d of selectedDocs(ws().ids)){const issue=egFileIssue(d,c);if(issue)errors.push(d.name+'：'+issue);}const out=[...new Set(errors)];if(show&&out.length)openModal('validation',{errors:out});return out;};
function egDropField(g,index){const deleted=g.rows[index].key;g.rows.splice(index,1);const names={};g.rows.forEach((r,i)=>{names[r.key]='F'+(i+1);r.key='F'+(i+1);});if(g.singleTable){const s=g.singleTable,llm=s.llm_config||{};for(const key of ['field_weights','field_prompt_rules'])if(llm[key])llm[key]=Object.fromEntries(Object.entries(llm[key]).filter(([k])=>k!==deleted).map(([k,v])=>[names[k]||k,v]));if(s.field_mapping)s.field_mapping=Object.fromEntries(Object.entries(s.field_mapping).filter(([k])=>k!==deleted).map(([k,v])=>[names[k]||k,v]));const remap=rules=>(rules||[]).filter(r=>!(r.logic==='and'?r.rules:[r]).some(q=>q.field===deleted)).map(r=>r.logic==='and'?{...r,rules:r.rules.map(q=>({...q,field:names[q.field]||q.field}))}:{...r,field:names[r.field]||r.field});llm.hard_rules=remap(llm.hard_rules);llm.veto_rules=remap(llm.veto_rules);llm.phase_check_field=llm.phase_check_field===deleted?g.rows[0]?.key||'':names[llm.phase_check_field]||llm.phase_check_field;}g.minFields=Math.min(g.minFields,g.rows.length);}
function egResultState(t){if(egView.task!==t.id)Object.assign(egView,{task:t.id,resultKind:'duplicate',resultQuery:'',resultDoc:'all',resultMethod:'all',resultPage:1});return egView;}
function egNormalize(t){const out=[],emit=(raw,kind,doc,block,extra={})=>{const refs=[...new Set([doc,...(Array.isArray(raw.refs)?raw.refs:[]),raw.other,raw.project1?.file_uuid,raw.project2?.file_uuid,extra.main?.file_uuid,extra.sub?.file_uuid].filter(Boolean))];const fields=t.config.engineering?.[kind]?.rows||[],labels={...Object.fromEntries(fields.map(r=>[r.key,r.a])),...(block?.field_score_labels||{}),...(block?.config_snapshot?.logical_field_mapping||{})};let a=raw.a,b=raw.b,source=raw.rows||[];if(raw.project1||raw.project2){a=raw.project1;b=raw.project2;source=[a,b];}if(extra.main){a=extra.main;b=extra.sub;source=[a,b];}const title=v=>typeof v==='object'?v?.[labels[fields[0]?.key]||fields[0]?.a]??v?.项目名称??Object.values(v||{})[0]:v;const method=raw.match_type==='code_exact'||extra.code?'code':'model',score=raw.weighted_score??raw.score??null;out.push({index:out.length,raw,kind,doc,refs,labels,source,a:title(a),b:title(b),score,method,reason:raw.reason??raw.detail??'',fieldScores:raw.field_scores||{},fieldWeights:block?.field_weights||block?.llm_config?.field_weights||block?.config_snapshot?.llm_config?.field_weights||{},group:extra.group??raw.group_id,block});};const entries=Array.isArray(t.result)?t.result:t.result?[t.result]:[];for(const r of entries){const doc=r.doc||r.file_uuid||(t.ids?.length===1?t.ids[0]:null);if(r.duplicate_detection||r.parent_child_analysis||r.duplicates){const dd=r.duplicate_detection||(r.duplicates?{duplicates:r.duplicates}:null),pc=r.parent_child_analysis;if(dd&&dd.status!=='failed')for(const x of dd.duplicates||[])emit(x,'duplicate',doc,dd);if(pc&&pc.status!=='failed')for(const group of pc.results||[])for(const sub of group.sub_projects||[])emit(sub,'parent',doc,pc,{main:group.main_project,sub:sub.project,code:group.match_type==='code_exact',group:group.group_id});}else emit(r,r.kind==='parent'||r.kind==='parent_child'?'parent':'duplicate',doc,null);}return out;}
function egReadable(t,r,download=false){return r.refs.length>0&&r.refs.every(id=>{const d=file(id),p=d&&!d.deleted&&auditFileAccess(d);return id===r.doc&&t.ids.includes(id)&&p?.read&&(!download||p.download);});}
tcOutput=function(t){const base=egBase.tcOutput(t);if(tcResolve(t)!=='engineering'||!['completed','partial'].includes(t.status)||tcBusy(t))return base;const rows=egNormalize(t).filter(r=>egReadable(t,r));return{...base,text:'重复 '+rows.filter(r=>r.kind==='duplicate').length+' 组 · 主子 '+rows.filter(r=>r.kind==='parent').length+' 组'};};
function egFiltered(t){const v=egResultState(t),q=v.resultQuery.trim().toLowerCase();return egNormalize(t).filter(r=>egReadable(t,r)&&r.kind===v.resultKind&&(v.resultDoc==='all'||r.doc===v.resultDoc)&&(v.resultMethod==='all'||r.method===v.resultMethod)&&[r.a,r.b,r.reason,file(r.doc)?.name].map(egText).join(' ').toLowerCase().includes(q));}
function egResultTable(t){const v=egResultState(t),rows=egFiltered(t),pages=Math.max(1,Math.ceil(rows.length/v.resultSize));v.resultPage=Math.max(1,Math.min(v.resultPage,pages));return '<div class="eg-result-scroll"><table class="eg-table eg-result-table"><thead><tr><th>来源台账</th><th>'+(v.resultKind==='parent'?'主项目':'项目记录一')+'</th><th>'+(v.resultKind==='parent'?'子项目':'项目记录二')+'</th><th>匹配方式 / 分数</th><th>核验</th></tr></thead><tbody>'+rows.slice((v.resultPage-1)*v.resultSize,v.resultPage*v.resultSize).map(r=>'<tr><td>'+E(file(r.doc)?.name||'来源已移除')+'</td><td>'+E(egText(r.a))+'</td><td>'+E(egText(r.b))+'</td><td>'+(r.method==='code'?tag('24位编码匹配','blue')+'<small>不经模型评分</small>':tag('模型比较','')+'<strong>'+E(r.score===null?'未返回分数':r.score+' / 5 分')+'</strong>')+'</td><td>'+A('原因与源行','eg-result-detail','data-index="'+r.index+'"')+'</td></tr>').join('')+'</tbody></table>'+(!rows.length?'<div class="eg-empty">本次没有符合筛选条件的候选关系。</div>':'')+'</div><div class="eg-pager"><span>共 <strong>'+rows.length+'</strong> 组候选</span><label>每页 <select data-eg-change="result-size" aria-label="每页候选数">'+[20,50,100].map(n=>'<option value="'+n+'" '+(n===v.resultSize?'selected':'')+'>'+n+'</option>').join('')+'</select> 组</label><div>'+B('上一页','eg-result-page','sm','data-step="-1" '+(v.resultPage===1?'disabled':''))+'<span>第 '+v.resultPage+' / '+pages+' 页</span>'+B('下一页','eg-result-page','sm','data-step="1" '+(v.resultPage===pages?'disabled':''))+'</div></div>';}
resultContent=function(t){if(t.toolId!=='engineering')return egBase.resultContent(t);const v=egResultState(t),all=egNormalize(t).filter(r=>egReadable(t,r)),errors=(Array.isArray(t.result)?t.result:[]).flatMap(r=>[['duplicate_detection','重复项目'],['parent_child_analysis','主子项目']].filter(([k])=>r[k]?.status==='failed').map(([k,n])=>n+'：'+egText(r[k].error||'本阶段未成功')));return '<section class="eg-results"><nav class="eg-result-tabs" aria-label="工程分析结果">'+EG_STAGES.map(([k,n])=>'<button data-action="eg-result-kind" data-kind="'+k+'" aria-pressed="'+(k===v.resultKind)+'" class="'+(k===v.resultKind?'active':'')+'">'+n+' <strong>'+all.filter(r=>r.kind===k).length+'</strong></button>').join('')+'</nav><p class="eg-result-note">候选关系来自同一份台账内部比较。请结合项目编码、建设内容和立项依据核验。</p>'+(errors.length?'<div class="notice">'+errors.map(E).join('<br>')+'</div>':'')+'<div class="eg-result-filters"><select data-eg-change="result-doc" aria-label="候选来源台账"><option value="all">全部台账</option>'+[...new Set(all.map(r=>r.doc))].map(id=>'<option value="'+E(id)+'" '+(v.resultDoc===id?'selected':'')+'>'+E(file(id)?.name)+'</option>').join('')+'</select><select data-eg-change="result-method" aria-label="候选匹配方式">'+[['all','全部匹配方式'],['model','模型比较'],['code','24位编码匹配']].map(([k,n])=>'<option value="'+k+'" '+(v.resultMethod===k?'selected':'')+'>'+n+'</option>').join('')+'</select><div class="search">'+I('search','icon-sm')+'<input data-eg-input="results" aria-label="查找项目候选" placeholder="查找项目、台账或分析原因" value="'+E(v.resultQuery)+'"></div>'+A('重置','eg-result-reset')+'</div><div id="eg-result-list" class="eg-result-list">'+egResultTable(t)+'</div></section>';};
function egSourceRows(r){const d=file(r.doc),rows=r.source;if(rows.length===2&&rows.every(Array.isArray))return simpleTable((d?.columns||[]).map(E),rows.map(a=>a.map(v=>E(egText(v)))),true);const columns=[...new Set(rows.flatMap(row=>row&&typeof row==='object'?Object.keys(row):[]))];return columns.length?simpleTable(['字段','项目记录一','项目记录二'],columns.map(col=>[E(col),E(egText(rows[0]?.[col])),E(egText(rows[1]?.[col]))]),true):'<p>本条未返回对应源行。</p>';}
function egDetail(){const t=currentTask(),r=egNormalize(t).find(r=>r.index===modalData.index);if(!r||!egReadable(t,r))return modalFrame('无法查看候选依据','','来源不在本次任务内、已移除或无查看权限。',B('关闭','close-modal'),'medium');const scoreRows=Object.entries(r.fieldScores).map(([key,value])=>[E(r.labels[key]||key),E(egText(value)),E(r.fieldWeights[key]===undefined?'未提供':Number(+r.fieldWeights[key]*100).toFixed(1)+'%')]);return modalFrame(r.kind==='parent'?'主子项目核验':'重复项目核验',E(file(r.doc)?.name||'项目台账'),'<div class="eg-detail-summary"><strong>'+E(egText(r.a))+'</strong><span>↔</span><strong>'+E(egText(r.b))+'</strong></div>'+(r.method==='code'?'<p class="notice">按24位项目编码匹配，不经过模型评分。原系统以固定值5记录此类匹配，不表示AI判定分数。</p>':'<p>模型加权总分：<strong>'+E(r.score===null?'未提供':r.score+' / 5')+'</strong></p>')+'<section><h3>分析原因</h3><p class="eg-preserve">'+E(r.reason||'本条未返回原因，请结合来源记录核验。')+'</p></section>'+(scoreRows.length&&r.method!=='code'?'<section><h3>各字段评分</h3>'+simpleTable(['比较字段','得分','权重'],scoreRows,true)+'</section>':'')+'<section><h3>对应源行</h3>'+egSourceRows(r)+'</section><section><h3>原始台账</h3>'+r.refs.map(id=>auditFileAccess(file(id)).preview?B(E(file(id)?.name),'source','sm','data-id="'+E(id)+'"'):'<p>'+E(file(id)?.name)+'（无预览权限）</p>').join('')+'</section>',B('关闭','close-modal'),'eg-evidence-dialog');}
modalContent=function(){if(!egActive())return egBase.modalContent();if(modal==='eg-field')return egFieldModal();if(modal==='eg-options')return egOptionsModal();if(modal==='eg-field-delete-confirm')return modalFrame('删除比较字段','只调整本次比较配置。','<p>删除“'+E(modalData.back.draft.name||modalData.back.draft.a)+'”后，引用该字段的比较条件会同步移除。</p>',B('取消','close-modal')+B('确认删除','eg-field-delete-confirm','danger'),'small');if(modal==='eg-result-detail')return egDetail();return egBase.modalContent();};
closeModal=function(){if(egActive()&&modal==='source'&&egSourceReturn){const back=egSourceReturn;egSourceReturn=null;egBase.closeModal();openModal('eg-result-detail',back);return;}if(modal==='eg-field-delete-confirm'){openModal('eg-field',modalData.back);return;}return egBase.closeModal();};
function egExportRows(t,scope='all'){const rows=egNormalize(t).filter(r=>egReadable(t,r,true)&&(scope==='all'||r.doc===scope));return[['来源台账','候选关系','项目记录一','项目记录二','匹配方式','返回分数','分析原因','各字段得分','字段权重','源记录一','源记录二'],...rows.map(r=>[file(r.doc)?.name,r.kind==='parent'?'主子项目':'重复项目',egText(r.a),egText(r.b),r.method==='code'?'24位编码匹配（非模型评分）':'模型比较',r.score??'',r.reason,Object.entries(r.fieldScores).map(([k,v])=>(r.labels[k]||k)+'：'+egText(v)).join('；'),Object.entries(r.fieldWeights).map(([k,v])=>(r.labels[k]||k)+'：'+egText(v)).join('；'),egText(r.source[0]),egText(r.source[1])])];}
exportRows=function(t,scope='all'){return t.toolId==='engineering'?egExportRows(t,scope):egBase.exportRows(t,scope);};
doExport=function(){const t=currentTask();if(t?.toolId!=='engineering'||$('#export-format')?.value!=='json')return egBase.doExport();if(!trCanDownload(t))return toast('当前结果暂无下载权限。');const scope=$('#export-scope')?.value||'all',rows=egNormalize(t).filter(r=>egReadable(t,r,true)&&(scope==='all'||r.doc===scope));if(!rows.length)return toast('当前范围没有可导出的结果。');download((t.name||'工程项目分析')+'-结果.json',JSON.stringify({task:t.name,config:t.config,execution_config:t.configFragment,results:rows.map(r=>({kind:r.kind,source:r.doc,matching_method:r.method,field_labels:r.labels,field_weights:r.fieldWeights,result:r.raw,source_rows:r.source}))},null,2),'application/json;charset=utf-8');egBase.closeModal();};
handleAction=function(action,el){if(!egActive())return egBase.handleAction(action,el);const d=el?.dataset||{},v=egView;
 if(action==='eg-stage'){if(!EG_STAGES.some(([k])=>k===d.stage))return;v.stage=d.stage;v.query='';v.page=1;render();return;}
 if(action==='eg-panel'){v.panel=d.panel;render();return;}
 if(action==='eg-field'||action==='eg-field-new'){openModal('eg-field',egFieldDraft(action==='eg-field-new'?-1:Number(d.index)));return;}
 if(action==='eg-field-page'){v.page+=Number(d.step);egPaintFields();return;}
 if(action==='eg-options'){openModal('eg-options',{stage:v.stage,draft:structuredClone(egGroup())});return;}
 if(action==='eg-field-save'&&!currentTask()){const p=modalData,r=p.draft,g=egConfig().engineering[p.stage];r.name=r.name.trim();r.a=r.a.trim();r.rule=r.rule.trim();const error=!r.name||!r.a?'请填写比较内容与台账列名。':!Number.isFinite(+r.weight)||+r.weight<0||+r.weight>1?'评分权重应为0–100%。':!Number.isFinite(+r.threshold)||+r.threshold<0||+r.threshold>1?'预筛阈值应为0–1。':+r.weight>0&&!r.rule?'请填写参与评分字段的评分规则。':g.rows.some((q,i)=>i!==p.index&&q.a===r.a)?'该台账列已用于比较，请选择其他列。':'';if(error){$('#eg-field-error').textContent=error;return;}if(p.index<0)g.rows.push(structuredClone(r));else g.rows[p.index]=structuredClone(r);egBase.closeModal();render();return;}
 if(action==='eg-field-delete'&&!currentTask()){if(egGroup(modalData.stage).rows.length<=1)return toast('至少保留一个比较字段。');openModal('eg-field-delete-confirm',{back:structuredClone(modalData)});return;}
 if(action==='eg-field-delete-confirm'&&!currentTask()){const p=modalData.back;egDropField(egGroup(p.stage),p.index);egBase.closeModal();render();return;}
 if(action==='eg-options-save'&&!currentTask()){const g=modalData.draft;if(!Number.isInteger(+g.minFields)||+g.minFields<1||+g.minFields>g.rows.length){$('#eg-options-error').textContent='至少匹配的字段数应在当前字段数范围内。';return;}egConfig().engineering[modalData.stage]=structuredClone(g);egBase.closeModal();render();return;}
 if(action==='eg-result-kind'){v.resultKind=d.kind;v.resultPage=1;render();return;}
 if(action==='eg-result-page'){v.resultPage+=Number(d.step);$('#eg-result-list').innerHTML=egResultTable(currentTask());return;}
 if(action==='eg-result-reset'){Object.assign(v,{resultQuery:'',resultDoc:'all',resultMethod:'all',resultPage:1});render();return;}
 if(action==='eg-result-detail'||action==='result-detail'&&currentTask()){openModal('eg-result-detail',{index:Number(d.index)});return;}
 if(action==='source'&&modal==='eg-result-detail')egSourceReturn=structuredClone(modalData);
 if(egPreparing()&&['tw-preview','preview'].includes(action)){ws().preview=d.id;return egBase.handleAction('source',el);}
 if(egPreparing()&&action==='tw-panel'){v.panel=d.panel==='materials'?'materials':'config';render();return;}
 return egBase.handleAction(action,el);
};
window.addEventListener('input',e=>{if(!egActive())return;const el=e.target;if(el.dataset.egInput){e.stopImmediatePropagation();if(el.dataset.egInput==='fields'){egView.query=el.value;egView.page=1;egPaintFields();}else{egView.resultQuery=el.value;egView.resultPage=1;$('#eg-result-list').innerHTML=egResultTable(currentTask());}return;}if(currentTask())return;if(el.dataset.egConfig){e.stopImmediatePropagation();egGroup()[el.dataset.egConfig]=el.value===''?'':Number(el.value);persist();return;}if(modal==='eg-field'&&el.dataset.egEdit){e.stopImmediatePropagation();const key=el.dataset.egEdit;modalData.draft[key]=['threshold','weight'].includes(key)?el.value===''?'':Number(el.value)/(key==='weight'?100:1):el.value;return;}if(modal==='eg-options'&&el.dataset.egOption){e.stopImmediatePropagation();const k=el.dataset.egOption,g=modalData.draft;if(k==='minFields')g[k]=el.value===''?'':Number(el.value);else if(k==='additional')g[k]=el.value;else{g.singleTable??={};g.singleTable.llm_config??={};g.singleTable.llm_config[k==='phase'?'phase_check_enabled':'phase_check_field']=k==='phase'?el.checked:el.value;}}},true);
window.addEventListener('change',e=>{if(!egActive())return;const el=e.target,k=el.dataset.egChange;if(k){e.stopImmediatePropagation();if(k==='field-size'){egView.size=Number(el.value);egView.page=1;egPaintFields();}else{if(k==='result-doc')egView.resultDoc=el.value;if(k==='result-method')egView.resultMethod=el.value;if(k==='result-size')egView.resultSize=Number(el.value);egView.resultPage=1;$('#eg-result-list').innerHTML=egResultTable(currentTask());}return;}if(modal==='eg-field'&&el.dataset.egEdit==='type'&&!currentTask()){e.stopImmediatePropagation();modalData.draft.type=el.value;}if(modal==='eg-options'&&el.dataset.egOption&&!currentTask()){const key=el.dataset.egOption;if(key==='phase'||key==='phaseField'){e.stopImmediatePropagation();const g=modalData.draft;g.singleTable??={};g.singleTable.llm_config??={};g.singleTable.llm_config[key==='phase'?'phase_check_enabled':'phase_check_field']=key==='phase'?el.checked:el.value;}}},true);
render();
